-- SEED DATA UNTUK SUPABASE (SISWA & MASTER POIN) - SMPN 1 RAJAPOLAH
-- Dijalankan di Supabase SQL Editor setelah menjalankan supabase_schema.sql
-- ============================================================================

-- 1. INSERT MASTER ATURAN POIN
ON CONFLICT (kode) DO UPDATE SET deskripsi = EXCLUDED.deskripsi, poin_default = EXCLUDED.poin_default;

-- 2. INSERT 1.094 DATA SISWA LENGKAP DENGAN FOTO
ON CONFLICT (nisn) DO UPDATE SET foto = EXCLUDED.foto, kelas = EXCLUDED.kelas, wali_kelas = EXCLUDED.wali_kelas;

